INSERT INTO faq (pertanyaan, jawaban, urutan) VALUES 
('Bagaimana cara mendaftar sebagai pengacara di Ruang Hukum?', 'Anda dapat mendaftar dengan memilih peran pengacara pada menu registrasi, lalu melengkapi data diri serta nomor izin praktik untuk menunggu verifikasi dari Admin.', 1),
('Apakah layanan konsultasi hukum di sini berbayar?', 'Ruang Hukum menyediakan layanan konsultasi awal untuk membantu masyarakat mendapatkan akses informasi hukum dengan mudah sesuai ketentuan yang berlaku.', 2),
('Bagaimana cara mengubah status artikel yang saya tulis?', 'Sebagai Admin, Anda dapat mengubah status artikel melalui menu Kelola Artikel, lalu pilih Ubah pada artikel yang diinginkan dan ubah statusnya menjadi Terbit atau Draft.', 3);